using System;
using System.Drawing;
using System.IO;
using System.Web.Script.Serialization;
using System.Windows.Forms;
namespace MacDeskNative {
 public static class EditDialogs {
  static T Clone<T>(T value){var s=new JavaScriptSerializer{MaxJsonLength=int.MaxValue};return s.Deserialize<T>(s.Serialize(value));}
  static string EditedValue(TextBox field,string original,bool trim){return field.Text==(original??"")?original:(trim?field.Text.Trim():field.Text);}
  public static DeskGroup Group(IWin32Window owner,DeskGroup existing){var result=existing==null?new DeskGroup{id=DesktopStore.NewId(),title="",subtitle=""}:Clone(existing);using(var d=new ShortDialog(existing==null?"新增文件夹":"编辑文件夹",240)){var title=d.Field("名称",result.title);var sub=d.Field("副标题",result.subtitle);d.Check=delegate{if(String.IsNullOrWhiteSpace(title.Text))return "请输入文件夹名称。";return null;};if(d.ShowDialog(owner)!=DialogResult.OK)return null;result.title=EditedValue(title,result.title,true);result.subtitle=EditedValue(sub,result.subtitle,true);return result;}}
  public static DeskItem Item(IWin32Window owner,DeskItem existing){var result=existing==null?new DeskItem{id=DesktopStore.NewId(),title="",description="",type="app",target="",icon="",arguments=""}:Clone(existing);using(var d=new ShortDialog(existing==null?"添加入口":"编辑入口",540)){var title=d.Field("名称",result.title);var description=d.Field("说明",result.description);d.Label("类型");var type=new ComboBox{Width=480,DropDownStyle=ComboBoxStyle.DropDownList,AccessibleName="入口类型"};type.Items.AddRange(new string[]{"应用程序","文件","文件夹","网址"});string[] types={"app","file","folder","url"};type.SelectedIndex=Math.Max(0,Array.IndexOf(types,result.type));d.Add(type);var target=d.Field("目标",result.target);d.Action("浏览目标…",delegate{if(type.SelectedIndex==2){using(var f=new FolderBrowserDialog()){if(f.ShowDialog(d)==DialogResult.OK){target.Text=f.SelectedPath;if(title.Text.Trim().Length==0)title.Text=Path.GetFileName(f.SelectedPath);}}}else if(type.SelectedIndex==3){target.Focus();}else using(var f=new OpenFileDialog{CheckFileExists=true}){if(f.ShowDialog(d)==DialogResult.OK){target.Text=f.FileName;if(title.Text.Trim().Length==0)title.Text=Path.GetFileNameWithoutExtension(f.FileName);}}});var arguments=d.Field("启动参数（仅应用程序）",result.arguments);arguments.Enabled=type.SelectedIndex==0;type.SelectedIndexChanged+=delegate{arguments.Enabled=type.SelectedIndex==0;};var icon=d.Field("图标（可选，留空为默认）",result.icon);d.Action("选择图标…",delegate{using(var f=new OpenFileDialog{Filter="图片|*.png;*.jpg;*.jpeg;*.ico;*.bmp;*.gif",CheckFileExists=true}){if(f.ShowDialog(d)==DialogResult.OK)icon.Text=f.FileName;}});d.Check=delegate{try{if(String.IsNullOrWhiteSpace(title.Text))return "请输入名称。";EntryServices.ValidateTarget(types[type.SelectedIndex],target.Text.Trim(),false);if(icon.Text.Trim().Length>0&&(!Path.IsPathRooted(icon.Text.Trim())||!File.Exists(icon.Text.Trim())))return "请选择存在的完整图标路径，或留空。";if(icon.Text.Trim().Length>0){using(var preview=Image.FromFile(icon.Text.Trim())){if(preview.Width<1)return "图标图片无效。";}}return null;}catch(Exception ex){return ex.Message;}};if(d.ShowDialog(owner)!=DialogResult.OK)return null;result.title=EditedValue(title,result.title,true);result.description=EditedValue(description,result.description,true);result.type=types[type.SelectedIndex];string validatedTarget=EntryServices.ValidateTarget(result.type,target.Text.Trim(),false);result.target=target.Text==(result.target??"")?result.target:validatedTarget;result.icon=EditedValue(icon,result.icon,true);result.arguments=EditedValue(arguments,result.arguments,false);return result;}}
  sealed class ShortDialog:Form {
   FlowLayoutPanel fields=new FlowLayoutPanel();public Func<string> Check;
   public ShortDialog(string title,int height){Text=title;AutoScaleMode=AutoScaleMode.None;ClientSize=new Size(530,height);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;ShowInTaskbar=false;StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",13,FontStyle.Regular,GraphicsUnit.Pixel);BackColor=Color.FromArgb(27,31,39);ForeColor=Color.WhiteSmoke;AccessibleName=title;fields.Dock=DockStyle.Fill;fields.FlowDirection=FlowDirection.TopDown;fields.WrapContents=false;fields.AutoScroll=true;fields.Padding=new Padding(18,10,10,8);var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=50,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(8)};var ok=new Button{Text="确定",AccessibleName="确定",Width=80,Height=30};ok.Click+=delegate{string error=Check==null?null:Check();if(error!=null){MessageBox.Show(this,error,"请检查输入",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}DialogResult=DialogResult.OK;};var cancel=new Button{Text="取消",AccessibleName="取消",DialogResult=DialogResult.Cancel,Width=80,Height=30};footer.Controls.Add(ok);footer.Controls.Add(cancel);Controls.Add(fields);Controls.Add(footer);AcceptButton=ok;CancelButton=cancel;Theme(footer);}
   void Theme(Control c){c.ForeColor=Color.WhiteSmoke;c.BackColor=Color.FromArgb(35,40,50);var b=c as Button;if(b!=null)b.FlatStyle=FlatStyle.Flat;foreach(Control child in c.Controls)Theme(child);}
   public void Add(Control c){fields.Controls.Add(c);Theme(c);}
   public void Label(string text){Add(new Label{Text=text,AutoSize=true,Margin=new Padding(0,5,0,1)});}
   public TextBox Field(string label,string value){Label(label);var t=new TextBox{Text=value??"",Width=480,AccessibleName=label};Add(t);return t;}
   public void Action(string title,Action action){var b=new Button{Text=title,AccessibleName=title,AutoSize=true,Height=27};b.Click+=delegate{action();};Add(b);}
  }
 }
}
